    /// available.
    /// </param>
    public static void GetJoystickGUIDInfo(SdlGuid guid, out ushort vendor, out ushort product, out ushort version, out ushort crc16)
    {
        vendor = default;
        product = default;
        version = default;
        crc16 = default;
        fixed (ushort* vendorPtr = &vendor)
        fixed (ushort* productPtr = &product)
        fixed (ushort* versionPtr = &version)
        fixed (ushort* crc16Ptr = &crc16)
